test('lineTotal calculates qty × unitPrice', () => {
  assert.equal(lineTotal({ qty: 5, unitPrice: 9500 }), 47500);
  assert.equal(lineTotal({ qty: 1, unitPrice: 120000 }), 120000);
  assert.equal(lineTotal({ qty: 100, unitPrice: 37 }), 3700);
});

test('lineTotal with single unit', () => {
  assert.equal(lineTotal({ qty: 1, unitPrice: 8500 }), 8500);
});

test('invoiceTotals sums line totals for subtotal', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 5 },
      { sku: 'DES-HOUR', qty: 3 },
    ],
  });
  const totals = invoiceTotals(result.value);
  assert.equal(totals.subtotal, 5 * 9500 + 3 * 8500);
  assert.equal(totals.subtotal, 73000);
});

test('invoiceTotals total equals subtotal for now', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 5 },
      { sku: 'LOGO-PACK', qty: 1 },
    ],
  });
  const totals = invoiceTotals(result.value);
  assert.equal(totals.total, totals.subtotal);
});

test('invoiceTotals with empty lines', () => {
  const totals = invoiceTotals({ lines: [] });
  assert.equal(totals.subtotal, 0);
  assert.equal(totals.total, 0);
});

test('invoiceTotals with single line', () => {
  const totals = invoiceTotals({
    lines: [{ qty: 10, unitPrice: 5000 }],
  });
  assert.equal(totals.subtotal, 50000);
  assert.equal(totals.total, 50000);
});
